import{_ as e,o as a,c as t,a2 as r}from"./chunks/framework.DQhM5RF8.js";const g=JSON.parse('{"title":"How to Join LlamaCraft","description":"","frontmatter":{},"headers":[],"relativePath":"info/how-to-join.md","filePath":"info/how-to-join.md"}'),n={name:"info/how-to-join.md"};function i(l,o,s,d,c,h){return a(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="how-to-join-llamacraft" tabindex="-1">How to Join LlamaCraft <a class="header-anchor" href="#how-to-join-llamacraft" aria-label="Permalink to &quot;How to Join LlamaCraft&quot;">​</a></h1><p>You can play on LlamaCraft using almost any device that runs Minecraft!</p><hr><h2 id="server-address" tabindex="-1">Server Address <a class="header-anchor" href="#server-address" aria-label="Permalink to &quot;Server Address&quot;">​</a></h2><ul><li><strong>Server IP</strong>: <code>164.152.106.210</code></li><li><strong>Java Port</strong>: <code>25565</code></li><li><strong>Bedrock Port</strong>: <code>19132</code></li></ul><hr><h2 id="_1-java-edition-pc-mac" tabindex="-1">1. Java Edition (PC &amp; Mac) <a class="header-anchor" href="#_1-java-edition-pc-mac" aria-label="Permalink to &quot;1. Java Edition (PC &amp; Mac)&quot;">​</a></h2><ol><li>Open Minecraft Java Edition (<code>1.20</code> or <code>1.21</code>).</li><li>Click <strong>Multiplayer</strong> then <strong>Add Server</strong>.</li><li>Put <code>LlamaCraft</code> as the Server Name.</li><li>Type <code>164.152.106.210</code> as the Server Address.</li><li>Click <strong>Done</strong> and double-click to join!</li></ol><hr><h2 id="_2-bedrock-phone-ipad-tablet-windows-10-11" tabindex="-1">2. Bedrock (Phone, iPad, Tablet, Windows 10/11) <a class="header-anchor" href="#_2-bedrock-phone-ipad-tablet-windows-10-11" aria-label="Permalink to &quot;2. Bedrock (Phone, iPad, Tablet, Windows 10/11)&quot;">​</a></h2><ol><li>Open Minecraft on your phone, iPad, or computer.</li><li>Click <strong>Play</strong> and tap the <strong>Servers</strong> tab at the top.</li><li>Scroll all the way down and tap <strong>Add Server</strong>.</li><li>Fill in: <ul><li><strong>Server Name</strong>: <code>LlamaCraft</code></li><li><strong>Server Address</strong>: <code>164.152.106.210</code></li><li><strong>Port</strong>: <code>19132</code></li></ul></li><li>Click <strong>Play</strong> to jump right in!</li></ol><hr><h2 id="_3-consoles-xbox-playstation-nintendo-switch" tabindex="-1">3. Consoles (Xbox, PlayStation, Nintendo Switch) <a class="header-anchor" href="#_3-consoles-xbox-playstation-nintendo-switch" aria-label="Permalink to &quot;3. Consoles (Xbox, PlayStation, Nintendo Switch)&quot;">​</a></h2><p>Consoles don&#39;t have an &quot;Add Server&quot; button by default, but you can join easily using your phone:</p><ol><li>Download the free app called <strong>MC Server Connector</strong> (or <strong>BedrockTogether</strong>) on your phone.</li><li>Make sure your phone is connected to the same home Wi-Fi as your console.</li><li>In the phone app, type IP <code>164.152.106.210</code> and Port <code>19132</code>, then tap <strong>Start</strong>.</li><li>On your console, open Minecraft, go to <strong>Friends</strong>, and look under <strong>LAN Games</strong>. Click <code>LlamaCraft</code> to join!</li></ol>',15)])])}const u=e(n,[["render",i]]);export{g as __pageData,u as default};
